const ARCHIVE_WHITESPACE = /^[\u0020\u0009\u000D]*$/;

function parseArchiveRecord(text, line) {
  if (ARCHIVE_WHITESPACE.test(text)) return { empty: true };

  try {
    return { empty: false, value: JSON.parse(text) };
  } catch (error) {
    const syntaxError =
      error instanceof SyntaxError ? error : new SyntaxError(String(error));
    syntaxError.code = "INVALID_RECORD";
    syntaxError.line = line;
    throw syntaxError;
  }
}

async function* readArchive(chunks) {
  const iterator = chunks[Symbol.asyncIterator]();
  const decoder = new TextDecoder("utf-8");
  let buffer = "";
  let line = 1;
  let reachedEOF = false;
  let activeError = null;

  try {
    while (true) {
      let newline;

      while ((newline = buffer.indexOf("\n")) !== -1) {
        let record = buffer.slice(0, newline);
        buffer = buffer.slice(newline + 1);

        if (record.endsWith("\r")) {
          record = record.slice(0, -1);
        }

        const parsed = parseArchiveRecord(record, line++);
        if (!parsed.empty) yield parsed.value;
      }

      const step = await iterator.next();

      if (step.done) {
        reachedEOF = true;
        buffer += decoder.decode();

        if (buffer.length !== 0) {
          const parsed = parseArchiveRecord(buffer, line);
          buffer = "";
          if (!parsed.empty) yield parsed.value;
        }

        return;
      }

      buffer += decoder.decode(step.value, { stream: true });
    }
  } catch (error) {
    activeError = error;
    throw error;
  } finally {
    if (!reachedEOF && typeof iterator.return === "function") {
      try {
        await iterator.return();
      } catch (cleanupError) {
        if (activeError === null) throw cleanupError;
      }
    }
  }
}
